class User {
    String name;
    int age;

    // 생성자 (Constructor)
    User(String name, int age) {
        this.name = name;
        this.age = age;
        System.out.println("User Created: " + this.name);
    }
}

public class Main {
    public static void main(String[] args) {
        User u1 = new User("Alice", 20);
        User u2 = new User("Bob", 25);
    }
}
